fn expand_unit_interval(value: Q30Interval, maximum_delta: Q30) -> Result<Q30Interval, FocError> {
    if maximum_delta < Q30::ZERO {
        return Err(FocError::Phase);
    }
    let lower = (i64::from(value.lower().bits()) - i64::from(maximum_delta.bits()))
        .max(i64::from(Q30::NEG_ONE.bits()));
    let upper = (i64::from(value.upper().bits()) + i64::from(maximum_delta.bits()))
        .min(i64::from(Q30::ONE.bits()));
    Q30Interval::new(
        Q30::from_bits(i32::try_from(lower).map_err(|_| FocError::Range)?),
        Q30::from_bits(i32::try_from(upper).map_err(|_| FocError::Range)?),
    )
}

fn pi_and_factorial_intervals_have_integer_certificates() {
        let scale = i128::from(Q30_SCALE);
        for (interval, denominator) in [
            (INV_2_FACTORIAL, 2_i128),
            (INV_3_FACTORIAL, 6),
            (INV_4_FACTORIAL, 24),
            (INV_5_FACTORIAL, 120),
            (INV_6_FACTORIAL, 720),
            (INV_7_FACTORIAL, 5_040),
            (INV_8_FACTORIAL, 40_320),
            (INV_9_FACTORIAL, 362_880),
            (INV_10_FACTORIAL, 3_628_800),
            (INV_11_FACTORIAL, 39_916_800),
            (INV_12_FACTORIAL, 479_001_600),
        ] {
            assert!(i128::from(interval.lower().bits()) * denominator <= scale);
            assert!(scale <= i128::from(interval.upper().bits()) * denominator);
            assert!(interval.width_ulps() <= 1);
        }

        let (atan_fifth_lower, atan_fifth_upper) = atan_reciprocal_bounds(5, 20);
        let (atan_239_lower, atan_239_upper) = atan_reciprocal_bounds(239, 6);
        let machin_lower = 4 * atan_fifth_lower - atan_239_upper;
        let machin_upper = 4 * atan_fifth_upper - atan_239_lower;
        let q30_to_certificate = 1_i128 << (96 - 30);
        assert!(i128::from(PI_OVER_4.lower().bits()) * q30_to_certificate <= machin_lower);
        assert!(machin_upper <= i128::from(PI_OVER_4.upper().bits()) * q30_to_certificate);
        assert_eq!(PI_OVER_4.width_ulps(), 1);

        let root_lower = i128::from(INV_SQRT_2.lower().bits());
        let root_upper = i128::from(INV_SQRT_2.upper().bits());
        assert!(2 * root_lower * root_lower <= scale * scale);
        assert!(scale * scale <= 2 * root_upper * root_upper);
    }

fn atan_reciprocal_bounds(divisor: i128, terms: usize) -> (i128, i128) {
        let scale = 1_i128 << 96;
        let square = divisor * divisor;
        let mut power = divisor;
        let mut lower = 0_i128;
        let mut upper = 0_i128;
        for index in 0..terms {
            let denominator = (2 * index as i128 + 1) * power;
            let term_lower = scale / denominator;
            let term_upper = term_lower + i128::from(scale.rem_euclid(denominator) != 0);
            if index.is_multiple_of(2) {
                lower += term_lower;
                upper += term_upper;
            } else {
                lower -= term_upper;
                upper -= term_lower;
            }
            power *= square;
        }
        let next_denominator = (2 * terms as i128 + 1) * power;
        let next_upper =
            scale / next_denominator + i128::from(scale.rem_euclid(next_denominator) != 0);
        if terms.is_multiple_of(2) {
            upper += next_upper;
        } else {
            lower -= next_upper;
        }
        (lower, upper)
    }

fn complete_actor_and_prepared_transition_have_fixed_small_bounds() {
        let actor = core::mem::size_of::<ServoFocAxisController>();
        let activation = core::mem::size_of::<PreparedServoFocAxisActivation>();
        let transition = core::mem::size_of::<PreparedServoFocAxisTransition>();
        let update = core::mem::size_of::<ServoFocAxisPreparedUpdate>();
        assert!(
            actor <= MAX_SERVO_FOC_AXIS_CONTROLLER_BYTES,
            "actor bytes: {actor}"
        );
        assert!(
            activation <= MAX_PREPARED_SERVO_FOC_AXIS_ACTIVATION_BYTES,
            "activation bytes: {activation}"
        );
        assert!(
            transition <= MAX_PREPARED_SERVO_FOC_AXIS_TRANSITION_BYTES,
            "transition bytes: {transition}"
        );
        assert!(
            update <= MAX_SERVO_FOC_AXIS_PREPARED_UPDATE_BYTES,
            "update bytes: {update}"
        );
        let two_axis_bank = core::mem::size_of::<ServoFocBank<2>>();
        let four_axis_activation = ServoFocBank::<MAX_SERVO_FOC_BANK_AXES>::prepare_activation(
            [profile(); MAX_SERVO_FOC_BANK_AXES],
            core::array::from_fn(|axis| ACTIVATION + axis as u64),
            [seed(); MAX_SERVO_FOC_BANK_AXES],
            FIRST_BOUNDARY,
        )
        .unwrap();
        assert_eq!(
            four_axis_activation.initial_images().len(),
            MAX_SERVO_FOC_BANK_AXES
        );
        let four_axis_activation = core::mem::size_of_val(&four_axis_activation);
        let two_axis_transition = core::mem::size_of::<PreparedServoFocBankTransition<2>>();
        assert!(
            two_axis_bank <= 2 * MAX_SERVO_FOC_AXIS_CONTROLLER_BYTES + 128,
            "two-axis bank bytes: {two_axis_bank}"
        );
        assert!(
            two_axis_transition <= 2 * MAX_PREPARED_SERVO_FOC_AXIS_TRANSITION_BYTES + 32,
            "two-axis transition bytes: {two_axis_transition}"
        );
        assert!(
            four_axis_activation <= MAX_PREPARED_SERVO_FOC_BANK_ACTIVATION_BYTES,
            "four-axis activation bytes: {four_axis_activation}"
        );
    }

fn widen_interval(value: Q30Interval, error: Q30) -> Result<Q30Interval, FocError> {
    if error < Q30::ZERO {
        return Err(FocError::CurrentCalibration);
    }
    Q30Interval::new(
        value.lower().checked_sub(error)?,
        value.upper().checked_add(error)?,
    )
}

fn interval_within_limit(value: Q30Interval, limit: Q30) -> bool {
    if limit < Q30::ZERO {
        return false;
    }
    let Ok(negative_limit) = limit.checked_neg() else {
        return false;
    };
    value.lower() >= negative_limit && value.upper() <= limit
}

fn position_interval(
    profile: ServoEncoderProfile,
    unwrapped_count: i64,
) -> Result<ServoPositionInterval, ServoEncoderError> {
    let error_numerator = i128::from(profile.maximum_count_error.numerator());
    let error_denominator = i128::from(profile.maximum_count_error.denominator());
    let center = i128::from(unwrapped_count)
        .checked_mul(error_denominator)
        .ok_or(ServoEncoderError::Arithmetic)?;
    let lower_count = center
        .checked_sub(error_numerator)
        .ok_or(ServoEncoderError::Arithmetic)?;
    let upper_count = center
        .checked_add(error_numerator)
        .ok_or(ServoEncoderError::Arithmetic)?;
    let scale_numerator = i128::from(profile.scale.position_bits_per_turn_numerator);
    let denominator = error_denominator
        .checked_mul(i128::from(profile.counts_per_mechanical_turn))
        .and_then(|value| {
            value.checked_mul(i128::from(profile.scale.position_bits_per_turn_denominator))
        })
        .ok_or(ServoEncoderError::Arithmetic)?;
    let lower_delta = lower_count
        .checked_mul(scale_numerator)
        .map(|value| div_floor(value, denominator))
        .ok_or(ServoEncoderError::Arithmetic)?;
    let upper_delta = upper_count
        .checked_mul(scale_numerator)
        .map(|value| div_ceil(value, denominator))
        .ok_or(ServoEncoderError::Arithmetic)?;
    let reference = i128::from(profile.position_at_reference.bits());
    let lower = reference
        .checked_add(lower_delta)
        .ok_or(ServoEncoderError::Arithmetic)?;
    let upper = reference
        .checked_add(upper_delta)
        .ok_or(ServoEncoderError::Arithmetic)?;
    let lower = i64::try_from(lower).map_err(|_| ServoEncoderError::PositionRange)?;
    let upper = i64::try_from(upper).map_err(|_| ServoEncoderError::PositionRange)?;
    ServoPositionInterval::new(
        ServoPosition::from_bits(lower),
        ServoPosition::from_bits(upper),
    )
    .map_err(|_| ServoEncoderError::Arithmetic)
}

fn velocity_interval(
    profile: ServoEncoderProfile,
    delta_counts: i64,
) -> Result<Q30Interval, ServoEncoderError> {
    let error_numerator = i128::from(profile.maximum_count_error.numerator());
    let error_denominator = i128::from(profile.maximum_count_error.denominator());
    let center = i128::from(delta_counts)
        .checked_mul(error_denominator)
        .ok_or(ServoEncoderError::Arithmetic)?;
    let complete_error = error_numerator
        .checked_mul(2)
        .ok_or(ServoEncoderError::Arithmetic)?;
    let lower_count = center
        .checked_sub(complete_error)
        .ok_or(ServoEncoderError::Arithmetic)?;
    let upper_count = center
        .checked_add(complete_error)
        .ok_or(ServoEncoderError::Arithmetic)?;
    let numerator_scale = i128::from(profile.device_cycle_hz)
        .checked_mul(i128::from(
            profile.scale.counts_per_second_at_velocity_one_denominator,
        ))
        .and_then(|value| value.checked_mul(i128::from(Q30_SCALE)))
        .ok_or(ServoEncoderError::Arithmetic)?;
    let denominator = error_denominator
        .checked_mul(i128::from(profile.sample_period_cycles))
        .and_then(|value| {
            value.checked_mul(i128::from(
                profile.scale.counts_per_second_at_velocity_one_numerator,
            ))
        })
        .ok_or(ServoEncoderError::Arithmetic)?;
    let lower_bits = lower_count
        .checked_mul(numerator_scale)
        .map(|value| div_floor(value, denominator))
        .ok_or(ServoEncoderError::Arithmetic)?;
    let upper_bits = upper_count
        .checked_mul(numerator_scale)
        .map(|value| div_ceil(value, denominator))
        .ok_or(ServoEncoderError::Arithmetic)?;
    let lower_bits = lower_bits
        .checked_sub(i128::from(profile.maximum_velocity_estimation_error.bits()))
        .ok_or(ServoEncoderError::Arithmetic)?;
    let upper_bits = upper_bits
        .checked_add(i128::from(profile.maximum_velocity_estimation_error.bits()))
        .ok_or(ServoEncoderError::Arithmetic)?;
    let maximum = i128::from(profile.maximum_admitted_velocity.bits());
    if lower_bits < -maximum || upper_bits > maximum {
        return Err(ServoEncoderError::VelocityRange {
            lower_bits,
            upper_bits,
            maximum_absolute_bits: profile.maximum_admitted_velocity.bits(),
        });
    }
    let lower = i32::try_from(lower_bits).map_err(|_| ServoEncoderError::Arithmetic)?;
    let upper = i32::try_from(upper_bits).map_err(|_| ServoEncoderError::Arithmetic)?;
    Q30Interval::new(Q30::from_bits(lower), Q30::from_bits(upper))
        .map_err(|_| ServoEncoderError::Arithmetic)
}

fn forward_wrap_produces_outward_position_and_velocity_intervals() {
        let mut estimator = estimator(4_094);
        let estimate = estimator.observe(observation(2, 2_000)).unwrap();
        assert_eq!(estimate.raw_count, 2);
        assert_eq!(estimate.directed_count, 2);
        assert_eq!(estimate.delta_counts, 4);
        assert_eq!(estimate.unwrapped_count, 4_098);
        assert_eq!(estimate.sample.sequence, 1);
        assert_eq!(estimate.sample.sampled_at, DeviceCycle(2_000));
        assert_eq!(
            estimate.sample.position,
            ServoPositionInterval::new(
                ServoPosition::from_bits(
                    4_098 * POSITION_BITS_PER_COUNT - POSITION_BITS_PER_COUNT / 2
                ),
                ServoPosition::from_bits(
                    4_098 * POSITION_BITS_PER_COUNT + POSITION_BITS_PER_COUNT / 2
                ),
            )
            .unwrap()
        );
        assert_eq!(
            estimate.sample.velocity,
            Q30Interval::new(
                Q30::from_bits(3 * VELOCITY_BITS_PER_COUNT - VELOCITY_ESTIMATION_ERROR),
                Q30::from_bits(5 * VELOCITY_BITS_PER_COUNT + VELOCITY_ESTIMATION_ERROR),
            )
            .unwrap()
        );
        assert_eq!(
            estimate.sample.velocity.width_ulps(),
            u64::from(VELOCITY_WIDTH)
        );

        let second = estimator.observe(observation(5, 3_000)).unwrap();
        assert_eq!(second.delta_counts, 3);
        assert_eq!(second.unwrapped_count, 4_101);
        assert_eq!(second.sample.sequence, 2);
    }

fn non_power_of_two_negative_position_and_velocity_bounds_are_outward() {
        let position_numerator = 5_u64 * (1_u64 << 32);
        let profile = ServoEncoderProfile {
            configuration_digest: DIGEST,
            counts_per_mechanical_turn: 12,
            count_at_reference: 3,
            direction: RotorCountDirection::Increasing,
            maximum_count_error: CountUncertainty::new(1, 3).unwrap(),
            position_at_reference: ServoPosition::from_bits(123),
            scale: ServoEncoderScale::new(position_numerator, 3, 30, 1).unwrap(),
            device_cycle_hz: 1_000,
            sample_period_cycles: 100,
            maximum_observation_latency_cycles: 10,
            maximum_trackable_velocity: Q30::ONE,
            maximum_admitted_velocity: Q30::ONE,
            maximum_velocity_estimation_error: Q30::from_bits(7),
            maximum_position_interval_width_ulps: u64::MAX,
            maximum_velocity_interval_width_ulps: u32::MAX,
        };
        assert_eq!(profile.maximum_observed_delta_counts(), Ok(4));
        let mut estimator = ServoEncoderEstimator::new(
            profile,
            ServoEncoderSeed {
                observation: ServoEncoderObservation {
                    configuration_digest: DIGEST,
                    raw_count: 3,
                    sampled_at: DeviceCycle(100),
                    available_at: DeviceCycle(100),
                },
                turn_index: -1,
            },
        )
        .unwrap();
        let estimate = estimator
            .observe(ServoEncoderObservation {
                configuration_digest: DIGEST,
                raw_count: 4,
                sampled_at: DeviceCycle(200),
                available_at: DeviceCycle(200),
            })
            .unwrap();
        assert_eq!(estimate.unwrapped_count, -11);
        assert_eq!(estimate.delta_counts, 1);

        let position_denominator = 3_i128 * 12 * 3;
        let reference = 123_i128 * position_denominator;
        let lower_position_numerator =
            reference + (-11_i128 * 3 - 1) * i128::from(position_numerator);
        let upper_position_numerator =
            reference + (-11_i128 * 3 + 1) * i128::from(position_numerator);
        let lower_position = i128::from(estimate.sample.position.lower().bits());
        let upper_position = i128::from(estimate.sample.position.upper().bits());
        assert!(lower_position * position_denominator <= lower_position_numerator);
        assert!((lower_position + 1) * position_denominator > lower_position_numerator);
        assert!((upper_position - 1) * position_denominator < upper_position_numerator);
        assert!(upper_position * position_denominator >= upper_position_numerator);

        let velocity_denominator = 3_i128 * 100 * 30;
        let lower_velocity_numerator = 1_000_i128 * i128::from(Q30_SCALE);
        let upper_velocity_numerator = 5_000_i128 * i128::from(Q30_SCALE);
        let lower_velocity = i128::from(estimate.sample.velocity.lower().bits()) + 7;
        let upper_velocity = i128::from(estimate.sample.velocity.upper().bits()) - 7;
        assert!(lower_velocity * velocity_denominator <= lower_velocity_numerator);
        assert!((lower_velocity + 1) * velocity_denominator > lower_velocity_numerator);
        assert!((upper_velocity - 1) * velocity_denominator < upper_velocity_numerator);
        assert!(upper_velocity * velocity_denominator >= upper_velocity_numerator);
    }

fn precision_and_range_policies_fail_before_state_advances() {
        let mut narrow_position = profile(RotorCountDirection::Increasing);
        narrow_position.maximum_position_interval_width_ulps = POSITION_WIDTH - 1;
        assert_eq!(
            ServoEncoderEstimator::new(
                narrow_position,
                ServoEncoderSeed {
                    observation: observation(0, 1_000),
                    turn_index: 0,
                }
            ),
            Err(ServoEncoderError::PositionPrecision {
                width_ulps: POSITION_WIDTH,
                maximum_width_ulps: POSITION_WIDTH - 1,
            })
        );

        let mut narrow_velocity = profile(RotorCountDirection::Increasing);
        narrow_velocity.maximum_velocity_interval_width_ulps = VELOCITY_WIDTH - 1;
        let mut narrow_estimator = ServoEncoderEstimator::new(
            narrow_velocity,
            ServoEncoderSeed {
                observation: observation(0, 1_000),
                turn_index: 0,
            },
        )
        .unwrap();
        assert_eq!(
            narrow_estimator.observe(observation(4, 2_000)),
            Err(ServoEncoderError::VelocityPrecision {
                width_ulps: u64::from(VELOCITY_WIDTH),
                maximum_width_ulps: VELOCITY_WIDTH - 1,
            })
        );
        assert_eq!(narrow_estimator.estimate_sequence(), 0);

        let mut overspeed = estimator(0);
        assert!(matches!(
            overspeed.observe(observation(8, 2_000)),
            Err(ServoEncoderError::VelocityRange { .. })
        ));
        assert_eq!(overspeed.last_unwrapped_count(), 0);
    }

pub struct Q30Interval {
    lower: Q30,
    upper: Q30,
}

pub struct DqInterval {
    pub d: Q30Interval,
    pub q: Q30Interval,
}

fn interval_max(left: Q30Interval, right: Q30Interval) -> Q30Interval {
    Q30Interval {
        lower: left.lower.max(right.lower),
        upper: left.upper.max(right.upper),
    }
}

fn interval_min(left: Q30Interval, right: Q30Interval) -> Q30Interval {
    Q30Interval {
        lower: left.lower.min(right.lower),
        upper: left.upper.min(right.upper),
    }
}

fn scale_wide_interval(
    lower_bits: i64,
    upper_bits: i64,
    scale: Q30Interval,
) -> Result<Q30Interval, FocError> {
    // Clarke differences may exceed Q30's i32 endpoint range. Retain i64
    // storage through the product and round once before narrowing to Q30.
    let lower =
        FixedInterval::<i64, Q30_FRACTION_BITS>::point(lower_bits).expect("scale 30 is valid");
    let upper =
        FixedInterval::<i64, Q30_FRACTION_BITS>::point(upper_bits).expect("scale 30 is valid");
    // The generated difference's endpoints are ordered; their singleton hull
    // is the same exact closed interval without a second ingress boundary.
    let source = lower.hull(&upper);
    let coefficient = FixedInterval::<i64, Q30_FRACTION_BITS>::new(
        i64::from(scale.lower().bits()),
        i64::from(scale.upper().bits()),
    )
    .expect("ordered Q30 coefficient");
    Q30Interval::from_fixed(
        source
            .checked_mul(&coefficient)
            .and_then(|value| value.convert::<i32>()),
    )
}

fn clamp_i64_to_i32_bounds(value: i64, lower: Q30, upper: Q30) -> i32 {
    value.clamp(i64::from(lower.bits()), i64::from(upper.bits())) as i32
}

fn interval_arithmetic_is_outward_and_division_rejects_zero() {
        let one_third = q(1, 3);
        assert_eq!(one_third.width_ulps(), 1);
        let product = one_third.checked_mul(q(3, 2)).unwrap();
        assert!(product.contains(Q30::HALF));
        assert_eq!(q(1, -2), Q30Interval::point(point(-1, 2)));
        assert_eq!(q(-1, -2), Q30Interval::point(Q30::HALF));
        assert_eq!(
            Q30Interval::ONE.checked_div(Q30Interval::new(point(-1, 2), point(1, 2)).unwrap()),
            Err(FocError::DivideByZero)
        );
        assert_eq!(Q30::from_bits(i32::MIN).checked_neg(), Err(FocError::Range));
    }

fn transform_constant_intervals_have_integer_certificates() {
        let scale = i128::from(Q30_SCALE);
        assert!(3 * i128::from(TWO_THIRDS.lower().bits()) <= 2 * scale);
        assert!(2 * scale <= 3 * i128::from(TWO_THIRDS.upper().bits()));

        let inverse_lower = i128::from(INV_SQRT_3.lower().bits());
        let inverse_upper = i128::from(INV_SQRT_3.upper().bits());
        assert!(3 * inverse_lower * inverse_lower <= scale * scale);
        assert!(scale * scale <= 3 * inverse_upper * inverse_upper);

        let root_lower = i128::from(SQRT_3_OVER_2.lower().bits());
        let root_upper = i128::from(SQRT_3_OVER_2.upper().bits());
        assert!(4 * root_lower * root_lower <= 3 * scale * scale);
        assert!(3 * scale * scale <= 4 * root_upper * root_upper);
    }

fn min_max_modulation_contains_known_duties_and_rejects_overrange() {
        let result = space_vector_modulate(
            AlphaBeta {
                alpha: q(1, 2),
                beta: Q30Interval::ZERO,
            },
            Q30::ONE,
        )
        .unwrap();
        assert!(result.duties.a.contains(point(11, 16)));
        assert!(result.duties.b.contains(point(5, 16)));
        assert!(result.duties.c.contains(point(5, 16)));
        assert_eq!(
            phase_to_duty(Q30Interval::point(Q30::NEG_ONE), Q30::ONE).unwrap(),
            Q30Interval::ZERO
        );
        assert_eq!(
            phase_to_duty(Q30Interval::ONE, Q30::ONE).unwrap(),
            Q30Interval::ONE
        );
        assert_eq!(
            space_vector_modulate(
                AlphaBeta {
                    alpha: q(3, 2),
                    beta: Q30Interval::ZERO,
                },
                Q30::ONE,
            ),
            Err(FocError::ModulationRange)
        );
    }

fn range_pulse_and_quantization_policies_fail_closed() {
        let outside = Q30Interval::new(Q30::from_bits(-1), Q30::ZERO).unwrap();
        assert_eq!(
            contract(u32::MAX).lower(
                &parameters(),
                synchronization(),
                1,
                DeviceCycle(0),
                duties(outside),
            ),
            Err(PwmCompareError::DutyRange)
        );
        assert_eq!(
            contract(u32::MAX).lower(
                &parameters(),
                synchronization(),
                1,
                DeviceCycle(0),
                duties(Q30Interval::ZERO),
            ),
            Err(PwmCompareError::PulseWidth)
        );

        let one_third = Q30Interval::from_ratio(1, 3).unwrap();
        assert_eq!(
            contract(1).lower(
                &parameters(),
                synchronization(),
                1,
                DeviceCycle(0),
                duties(one_third),
            ),
            Err(PwmCompareError::Quantization)
        );
        assert_eq!(
            contract(u32::MAX).lower(
                &parameters(),
                synchronization(),
                0,
                DeviceCycle(0),
                duties(Q30Interval::HALF),
            ),
            Err(PwmCompareError::ZeroToken)
        );
    }

pub struct ServoPositionInterval {
    lower: ServoPosition,
    upper: ServoPosition,
}

pub enum ServoPositionIntervalError {
    /// The supplied upper endpoint preceded the lower endpoint.
    Order,
    /// A checked exact position operation overflowed Q31.32 storage.
    Arithmetic,
}

pub struct ServoPositionErrorInterval {
    lower_bits: i128,
    upper_bits: i128,
}

pub struct ServoQ30ErrorInterval {
    lower_bits: i64,
    upper_bits: i64,
}

fn q31_32_intervals_preserve_extreme_width_and_midpoint() {
        let interval = ServoPositionInterval::new(
            ServoPosition::from_bits(i64::MIN),
            ServoPosition::from_bits(i64::MAX),
        )
        .unwrap();
        assert_eq!(interval.width_ulps(), u64::MAX);
        assert_eq!(interval.midpoint(), ServoPosition::from_bits(-1));
        assert_eq!(
            ServoPositionInterval::new(ServoPosition::from_bits(1), ServoPosition::from_bits(0)),
            Err(ServoPositionIntervalError::Order)
        );
        assert_eq!(
            ServoPosition::from_bits(i64::MAX).checked_add_bits(1),
            Err(ServoPositionIntervalError::Arithmetic)
        );
    }
